  // ---------- Rendu ----------
  const AUTH = ["login", "otp"];
  function render() {
    const v = (location.hash.slice(1) || "dashboard");
    const view = V[v] ? v : "dashboard";
    const act = { user: "users", editor: "recipe", review: "reviews" }[view] || view;
    if (AUTH.includes(view)) { $("#app").innerHTML = V[view](); }
    else { $("#app").innerHTML = '<div class="app">' + side(act) + '<div class="main">' + top() + V[view]() + "</div></div>"; }
    $("#vm").innerHTML = '<button data-v="login" class="' + (view === "login" ? "on" : "") + '">Connexion</button><button data-v="otp" class="' + (view === "otp" ? "on" : "") + '">2FA</button><button data-v="dashboard" class="' + (!AUTH.includes(view) ? "on" : "") + '">Application</button><button data-v="user">Fiche utilisateur</button><button data-v="editor">Éditeur</button><button data-v="challenge">Règle challenge</button>';
    const r = $("#role"); if (r) r.onchange = (e) => { role = e.target.value; render(); };
    window.scrollTo(0, 0);
  }
  document.addEventListener("click", (e) => { const b = e.target.closest("#vm button"); if (b) location.hash = b.dataset.v; });
  window.addEventListener("hashchange", render);
  render();
